const _gold=Color(0xFFFFD36A); const _gold2=Color(0xFFB77921); const _bg=Color(0xFF090604); const _card=Color(0xFF1B0E08);
class GiftItem{final String id,name,emoji,category;final int price;final bool banner;const GiftItem({required this.id,required this.name,required this.emoji,required this.price,required this.category,this.banner=false});}
const gifts=<GiftItem>[
 GiftItem(id:'rose',name:'وردة',emoji:'🌹',price:100,category:'normal'),GiftItem(id:'heart',name:'قلب',emoji:'❤️',price:500,category:'love'),GiftItem(id:'kiss',name:'قبلة',emoji:'💋',price:1000,category:'love'),GiftItem(id:'diamond',name:'ماسة',emoji:'💎',price:2500,category:'luxury'),GiftItem(id:'love_letter',name:'رسالة حب',emoji:'💌',price:4000,category:'love'),GiftItem(id:'cp',name:'CP',emoji:'🫶',price:4000,category:'cp'),GiftItem(id:'brother',name:'علاقة أخوة',emoji:'🤝',price:4000,category:'brotherhood'),GiftItem(id:'crown',name:'تاج ملكي',emoji:'👑',price:10000,category:'luxury',banner:true),GiftItem(id:'dragon',name:'تنين',emoji:'🐉',price:10000,category:'normal',banner:true),GiftItem(id:'lion',name:'أسد',emoji:'🦁',price:25000,category:'normal',banner:true),GiftItem(id:'love_couple',name:'ثنائي الحب',emoji:'💞',price:50000,category:'love',banner:true),GiftItem(id:'royal_car',name:'سيارة ملكية',emoji:'🚘',price:50000,category:'luxury',banner:true),GiftItem(id:'gold_castle',name:'قصر ذهبي',emoji:'🏰',price:100000,category:'luxury',banner:true),GiftItem(id:'brother_royal',name:'رابطة إخوة ملكية',emoji:'🛡️',price:100000,category:'brotherhood',banner:true),GiftItem(id:'gold_dragon',name:'تنين ذهبي',emoji:'🐉',price:250000,category:'luxury',banner:true),GiftItem(id:'royal_throne',name:'عرش ملكي',emoji:'👑',price:500000,category:'luxury',banner:true),GiftItem(id:'asmar_kingdom',name:'مملكة Asmar',emoji:'🏯',price:1000000,category:'luxury',banner:true),GiftItem(id:'luck_10',name:'حظ 10',emoji:'🍀',price:10,category:'luck'),GiftItem(id:'luck_50',name:'حظ 50',emoji:'🍀',price:50,category:'luck'),GiftItem(id:'luck_100',name:'حظ 100',emoji:'🍀',price:100,category:'luck'),GiftItem(id:'luck_500',name:'حظ 500',emoji:'🎰',price:500,category:'luck'),GiftItem(id:'luck_1000',name:'حظ 1,000',emoji:'🎰',price:1000,category:'luck'),GiftItem(id:'luck_3000',name:'حظ 3,000',emoji:'✨',price:3000,category:'luck'),GiftItem(id:'luck_5000',name:'حظ 5,000',emoji:'✨',price:5000,category:'luck',banner:true),
