String giftCategoryLabel(String c)=>const {'love':'❤️ علاقة حب','brotherhood':'🤝 علاقة أخوة','cp':'🫶 CP','luck':'🍀 هدايا الحظ','luxury':'👑 فاخرة','normal':'🎁 عادية'}[c]??'🎁 الكل';
Future<void> emitGlobalGiftEvent({required String roomId,required String giftName,required int giftValue,required String receiverId})async{final db=Supabase.instance.client;try{final setting=await db.from('app_settings').select('int_value').eq('key','min_gift_value_for_banner').maybeSingle();final threshold=(setting?['int_value'] as num?)?.toInt()??10000;if(giftValue<threshold)return;final senderId=db.auth.currentUser?.id;if(senderId==null)return;final sender=await db.from('profiles').select('display_name,username').eq('id',senderId).maybeSingle();final receiver=await db.from('profiles').select('display_name,username').eq('id',receiverId).maybeSingle();final room=await db.from('rooms').select('name').eq('id',roomId).maybeSingle();await db.from('global_gift_events').insert({'sender_id':senderId,'sender_name':sender?['display_name']??sender?['username']??senderId,'receiver_id':receiverId,'receiver_name':receiver?['display_name']??receiver?['username']??receiverId,'gift_name':giftName,'gift_value':giftValue,'room_id':roomId,'room_name':room?['name']??roomId});}catch(_){}}
class GiftHistoryPage extends StatelessWidget{const GiftHistoryPage({super.key});@override Widget build(BuildContext context){final user=Supabase.instance.client.auth.currentUser;return Scaffold(backgroundColor:_bg,appBar:AppBar(title:const Text('سجل الهدايا 🎁')),body:user==null?const Center(child:Text('يجب تسجيل الدخول')):StreamBuilder<List<Map<String,dynamic>>>(stream:Supabase.instance.client.from('gift_transactions').stream(primaryKey:['id']).order('created_at',ascending:false),builder:(context,s){final rows=(s.data??[]).where((x)=>x['sender_id']==user.id||x['recipient_id']==user.id).take(100).toList();if(rows.isEmpty)return const Center(child:Text('لا توجد هدايا بعد 🎁'));return ListView.builder(padding:const EdgeInsets.all(16),itemCount:rows.length,itemBuilder:(context,i){final r=rows[i];return Card(color:_card,child:ListTile(leading:const Text('🎁',style:TextStyle(fontSize:30)),title:Text(r['sender_id']==user.id?'أرسلت هدية':'استلمت هدية'),subtitle:Text('هدية: ${r['gift_id']}'),trailing:Text('${r['amount']} 🪙',style:const TextStyle(color:_gold,fontWeight:FontWeight.bold))));});}));}}
class GiftSheet extends StatefulWidget{final String roomId;final void Function(GiftItem gift)? onSent;const GiftSheet({super.key,required this.roomId,this.onSent});@override State<GiftSheet> createState()=>_GiftSheetState();}
class _GiftSheetState extends State<GiftSheet>{String? recipient;int balance=0;bool sending=false;String category='all';@override void initState(){super.initState();_load();}Future<void> _load()async{final user=Supabase.instance.client.auth.currentUser;if(user==null)return;try{final row=await Supabase.instance.client.from('wallets').select('balance').eq('user_id',user.id).maybeSingle();if(mounted)setState(()=>balance=(row?['balance'] as num?)?.toInt()??0);}catch(_){}}
Future<void> _send(GiftItem gift)async{final target=recipient;if(target==null||target.isEmpty||sending)return;setState(()=>sending=true);try{await Supabase.instance.client.rpc('send_gift',params:{'p_room_id':widget.roomId,'p_recipient_id':target,'p_gift_id':gift.id});final dbGift=await Supabase.instance.client.from('gifts').select('name,price_coins,emoji').eq('id',gift.id).maybeSingle();final name=dbGift?['name']?.toString()??gift.name;final price=(dbGift?['price_coins'] as num?)?.toInt()??gift.price;final emoji=dbGift?['emoji']?.toString()??gift.emoji;await emitGlobalGiftEvent(roomId:widget.roomId,giftName:name,giftValue:price,receiverId:target);await _load();if(!mounted)return;widget.onSent?.call(GiftItem(id:gift.id,name:name,emoji:emoji,price:price,category:gift.category,banner:gift.banner));Navigator.pop(context);ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تم إرسال $emoji $name • $price 🪙')));}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تعذر إرسال الهدية: $e')));}finally{if(mounted)setState(()=>sending=false);}}
@override Widget build(BuildContext context){final shown=gifts.where((g)=>category=='all'||g.category==category).toList();return Directionality(textDirection:TextDirection.rtl,child:Container(padding:const EdgeInsets.fromLTRB(12,14,12,20),decoration:const BoxDecoration(color:Color(0xFF120805),borderRadius:BorderRadius.vertical(top:Radius.circular(28))),child:Column(mainAxisSize:MainAxisSize.min,children:[Row(children:[const Text('الهدايا الفاخرة 🎁',style:TextStyle(color:_gold,fontSize:21,fontWeight:FontWeight.w900)),const Spacer(),Text('$balance 🪙',style:const TextStyle(color:_gold,fontWeight:FontWeight.bold)),IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const GiftHistoryPage())),icon:const Icon(Icons.history,color:_gold))]),TextField(onChanged:(v)=>setState(()=>recipient=v.trim().isEmpty?null:v.trim()),style:const TextStyle(color:Colors.white),decoration:const InputDecoration(labelText:'ID أو اسم المستخدم للمستلم',prefixIcon:Icon(Icons.person_search))),const SizedBox(height:10),SizedBox(height:42,child:ListView(scrollDirection:Axis.horizontal,children:[for(final c in const ['all','normal','love','cp','brotherhood','luck','luxury'])Padding(padding:const EdgeInsets.symmetric(horizontal:3),child:ChoiceChip(label:Text(giftCategoryLabel(c)),selected:category==c,onSelected:(_)=>setState(()=>category=c)))])),const SizedBox(height:8),Flexible(child:GridView.builder(shrinkWrap:true,itemCount:shown.length,gridDelegate:const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount:3,childAspectRatio:.82,crossAxisSpacing:8,mainAxisSpacing:8),itemBuilder:(context,index){final gift=shown[index];return InkWell(onTap:sending?null:()=>_send(gift),borderRadius:BorderRadius.circular(18),child:Container(decoration:BoxDecoration(borderRadius:BorderRadius.circular(18),gradient:LinearGradient(colors:gift.banner?[const Color(0xFF5C310B),const Color(0xFF1A0A05)]:[const Color(0xFF241207),const Color(0xFF100805)]),border:Border.all(color:gift.banner?_gold:_gold2,width:gift.banner?1.5:1)),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text(gift.emoji,style:const TextStyle(fontSize:38)),Text(gift.name,maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w900,fontSize:11)),Text('${gift.price} 🪙',style:const TextStyle(color:_gold,fontSize:10,fontWeight:FontWeight.bold))])));}))])));}}
